package main
import (
"github.com/gin-gonic/gin"
"net/http"
"strconv"
)
func main() {
r := gin.New()
r.Use(gin.Recovery())
r.GET("/double/:n", func(c *gin.Context) {
 n, err := strconv.Atoi(c.Param("n"))
 if err != nil { c.String(http.StatusBadRequest, "Use a whole number"); return }
 c.JSON(http.StatusOK, gin.H{"answer": n * 2})
})
r.Run("127.0.0.1:3000")
}
